<script setup lang="ts">
import { onMounted, ref } from 'vue';import { UploadCloud, Trash2, ExternalLink } from 'lucide-vue-next';import { api } from '@/services/api';import { errorMessage } from '@/utils/errors';import { fileSize } from '@/utils/format';import type { Media } from '@/types/api';import PageHeader from '@/components/PageHeader.vue';import PaginationBar from '@/components/PaginationBar.vue';import ConfirmDialog from '@/components/ConfirmDialog.vue';import EmptyState from '@/components/EmptyState.vue'
const rows=ref<Media[]>([]),page=ref(1),lastPage=ref(1),total=ref(0),uploading=ref(false),deleteId=ref<number|null>(null),err=ref('');async function load(p=page.value){const r=await api.media({page:p});rows.value=r.data;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}async function upload(e:Event){const files=(e.target as HTMLInputElement).files;if(!files?.length)return;uploading.value=true;err.value='';try{for(const f of Array.from(files))await api.uploadMedia(f);await load(1)}catch(e){err.value=errorMessage(e)}finally{uploading.value=false;(e.target as HTMLInputElement).value=''}}async function remove(){if(!deleteId.value)return;try{await api.deleteMedia(deleteId.value);deleteId.value=null;await load()}catch(e){alert(errorMessage(e))}}onMounted(()=>load())
</script>
<template><PageHeader title="Thư viện Media" description="Tệp tập trung trên Google Drive, dùng chung cho sản phẩm, bài viết và avatar."/><section class="card"><div class="card-body"><div v-if="err" class="alert alert-danger">{{err}}</div><div class="upload-zone"><label><UploadCloud :size="26"/><strong>{{uploading?'Đang upload lên Google Drive...':'Chọn ảnh để upload'}}</strong><p>Có thể chọn nhiều ảnh. Backend sẽ tạo quyền public và lưu media_id.</p><input type="file" accept="image/*" multiple :disabled="uploading" @change="upload"></label></div></div><EmptyState v-if="!rows.length" title="Thư viện đang trống"/><div v-else class="media-grid"><article class="media-card" v-for="x in rows" :key="x.media_id"><div class="media-thumb"><img :src="x.drive_view_url" :alt="x.file_name"/></div><div class="media-info"><strong :title="x.file_name">{{x.file_name}}</strong><small>#{{x.media_id}} · {{fileSize(x.size_bytes)}}</small></div><div class="media-actions"><a class="btn btn-secondary btn-sm" :href="x.drive_view_url" target="_blank"><ExternalLink :size="13"/></a><button class="btn btn-danger btn-sm" @click="deleteId=x.media_id"><Trash2 :size="13"/>Xóa</button></div></article></div><PaginationBar v-if="rows.length" :page="page" :last-page="lastPage" :total="total" @change="load"/></section><ConfirmDialog :open="!!deleteId" title="Xóa media" message="Media đang được sản phẩm, bài viết hoặc avatar tham chiếu có thể không xóa được hoặc làm mất ảnh. Backend sẽ kiểm tra trước khi xóa." @cancel="deleteId=null" @confirm="remove"/></template>
